import React, { useState, useEffect, useContext } from 'react';
import EventForm from './EventForm';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const Dashboard = () => {
  const [events, setEvents] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [expandedEvent, setExpandedEvent] = useState(null);
  const [newItemName, setNewItemName] = useState("");
  const { user, logout } = useContext(AuthContext) || {};
  const navigate = useNavigate();

  const currentUserId = user?.id || user?._id;
  
  // Dynamic LAN URL
  const API_BASE = `http://${window.location.hostname}:5000/api/events`;

  const fetchEvents = async () => {
    if (!currentUserId) return;
    try {
      const res = await axios.get(`${API_BASE}?userId=${currentUserId}`);
      setEvents(res.data);
      if (expandedEvent) {
        const updated = res.data.find(e => e._id === expandedEvent._id);
        setExpandedEvent(updated);
      }
    } catch (err) { console.error(err); }
  };

  useEffect(() => { fetchEvents(); }, [currentUserId]);

  const handleRSVP = async (e, eventId, isJoining) => {
    e.stopPropagation(); // Prevent opening the modal when clicking the button
    try {
      await axios.post(`${API_BASE}/${eventId}/rsvp`, {
        userId: currentUserId,
        status: isJoining ? 'joining' : 'leaving'
      });
      fetchEvents();
    } catch (err) { alert("Error updating RSVP"); }
  };

  const handleAddItem = async (e, eventId) => {
    e.preventDefault();
    if (!newItemName) return;
    try {
      await axios.post(`${API_BASE}/${eventId}/items`, {
        itemName: newItemName, userId: currentUserId, userName: user.name
      });
      setNewItemName("");
      fetchEvents();
    } catch (err) { alert("Error adding item"); }
  };

  const handleDeleteItem = async (eventId, itemId) => {
    try {
      await axios.delete(`${API_BASE}/${eventId}/items/${itemId}?userId=${currentUserId}`);
      fetchEvents();
    } catch (err) { alert(err.response?.data?.message || "Unauthorized"); }
  };

  const styles = {
    container: { minHeight: '100vh', background: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)', padding: '40px 20px', fontFamily: "'Segoe UI', Tahoma, Geneva, Verdana, sans-serif" },
    wrapper: { maxWidth: '1100px', margin: '0 auto' },
    header: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '40px', paddingBottom: '20px', borderBottom: '2px solid rgba(255,255,255,0.5)' },
    headerTitle: { fontSize: '2.5rem', fontWeight: '700', color: '#2d3436', letterSpacing: '-0.5px' },
    headerUser: { display: 'flex', alignItems: 'center', gap: '15px' },
    card: { backgroundColor: 'white', padding: '22px', borderRadius: '16px', cursor: 'pointer', boxShadow: '0 4px 15px rgba(0,0,0,0.08)', transition: 'all 0.3s ease', border: '1px solid rgba(255,255,255,0.8)', position: 'relative' },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '24px' },
    modalOverlay: { position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, background: 'rgba(0,0,0,0.5)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000, backdropFilter: 'blur(5px)' },
    modal: { background: 'white', padding: '35px', borderRadius: '20px', width: '90%', maxWidth: '500px', position: 'relative', boxShadow: '0 20px 60px rgba(0,0,0,0.3)', border: '1px solid rgba(255,255,255,0.2)' },
    itemRow: { display: 'flex', justifyContent: 'space-between', alignItems: 'center', padding: '14px 0', borderBottom: '1px solid #f0f2f5' },
    empty: { textAlign: 'center', padding: '100px 20px', color: '#636e72' },
    rsvpBtn: { padding: '6px 14px', borderRadius: '8px', border: 'none', cursor: 'pointer', fontWeight: '600', fontSize: '12px', transition: 'all 0.2s' }
  };

  return (
    <div style={styles.container}>
      <div style={styles.wrapper}>
        <div style={styles.header}>
          <h1 style={styles.headerTitle}>Dashboard</h1>
          <div style={styles.headerUser}>
            <span style={{ fontSize: '16px', color: '#2d3436', fontWeight: '500' }}>Welcome, {user?.name}</span>
            <button onClick={() => navigate('/')} style={{ padding: '10px 24px', backgroundColor: '#5f7983', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', fontSize: '14px' }}>← Back</button>
            <button onClick={() => { logout(); navigate('/'); }} style={{ padding: '10px 24px', backgroundColor: '#ff6b6b', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: '600', fontSize: '14px' }}>Logout</button>
          </div>
        </div>

        <div style={{ marginBottom: '40px' }}>
          <button onClick={() => setShowForm(!showForm)} style={{ padding: '12px 28px', backgroundColor: '#6c5ce7', color: 'white', border: 'none', borderRadius: '10px', cursor: 'pointer', fontWeight: '600', fontSize: '15px' }}>
            {showForm ? "✕ Close Form" : "+ Create Event"}
          </button>
          {showForm && (
            <div style={{ background: 'white', padding: '35px', borderRadius: '16px', marginTop: '20px', boxShadow: '0 10px 35px rgba(0,0,0,0.1)' }}>
              <EventForm user={user} onEventCreated={() => { fetchEvents(); setShowForm(false); }} />
            </div>
          )}
        </div>

        <h2 style={{ marginBottom: '24px', fontSize: '1.8rem', fontWeight: '700', color: '#2d3436' }}>Upcoming Events</h2>
        
        {events.length === 0 ? (
          <div style={styles.empty}><h3>No events yet</h3></div>
        ) : (
          <div style={styles.grid}>
            {events.map(e => {
              const isCreator = String(e.creator?._id || e.creator) === String(currentUserId);
              const isAttending = e.attendees?.some(a => String(a._id || a) === String(currentUserId));
              
              return (
                <div key={e._id} style={styles.card} onClick={() => setExpandedEvent(e)}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
                    <span style={{ fontSize: '11px', color: '#6c5ce7', fontWeight: '700', textTransform: 'uppercase' }}>
                      {isCreator ? "🎯 Organizer" : "👥 Guest"}
                    </span>
                    {!isCreator && (
                      <button 
                        onClick={(event) => handleRSVP(event, e._id, !isAttending)}
                        style={{ 
                          ...styles.rsvpBtn, 
                          backgroundColor: isAttending ? '#ffeaa7' : '#55efc4',
                          color: isAttending ? '#d6a031' : '#00b894'
                        }}
                      >
                        {isAttending ? "Leave" : "Join"}
                      </button>
                    )}
                  </div>
                  
                  <h3 style={{ margin: '12px 0 14px 0', fontSize: '1.3rem', fontWeight: '700', color: '#2d3436' }}>{e.name}</h3>
                  <p style={{ color: '#636e72', fontSize: '14px', marginBottom: '8px' }}>📍 {e.location}</p>
                  <p style={{ color: '#636e72', fontSize: '14px', marginBottom: '12px' }}>📅 {new Date(e.date).toLocaleDateString()}</p>
                  
                  <div style={{ display: 'flex', gap: '15px', marginTop: '14px', fontSize: '13px', fontWeight: '600' }}>
                    <span style={{ color: '#00b894' }}>📦 {e.items?.length || 0} items</span>
                    <span style={{ color: '#0984e3' }}>👥 {e.attendees?.length || 0} attending</span>
                  </div>
                </div>
              );
            })}
          </div>
        )}

        {/* MODAL FOR ITEMS & ATTENDEES */}
        {expandedEvent && (
          <div style={styles.modalOverlay} onClick={() => setExpandedEvent(null)}>
            <div style={styles.modal} onClick={e => e.stopPropagation()}>
              <h2 style={{ fontSize: '1.8rem', fontWeight: '700', color: '#2d3436', marginBottom: '4px' }}>{expandedEvent.name}</h2>
              <p style={{ color: '#6c5ce7', fontWeight: '600', marginBottom: '20px' }}>
                Organized by: {expandedEvent.creator?.name || 'Unknown'}
              </p>

              <h4 style={{ marginBottom: '10px' }}>Items ({expandedEvent.items.length})</h4>
              <div style={{ maxHeight: '180px', overflowY: 'auto', marginBottom: '20px', border: '1px solid #f0f2f5', padding: '10px', borderRadius: '8px' }}>
                {expandedEvent.items.map(item => (
                  <div key={item._id} style={styles.itemRow}>
                    <span style={{ fontSize: '14px' }}><strong>{item.name}</strong> <small style={{ color: '#99a9b9' }}>({item.addedByName})</small></span>
                    {(String(item.addedBy) === String(currentUserId) || String(expandedEvent.creator?._id || expandedEvent.creator) === String(currentUserId)) && (
                      <button onClick={() => handleDeleteItem(expandedEvent._id, item._id)} style={{ border: 'none', background: 'none', color: '#ff7675', cursor: 'pointer' }}>✕</button>
                    )}
                  </div>
                ))}
              </div>

              <form onSubmit={(e) => handleAddItem(e, expandedEvent._id)} style={{ display: 'flex', gap: '10px', marginBottom: '25px' }}>
                <input
                  placeholder="I'll bring..."
                  value={newItemName}
                  onChange={e => setNewItemName(e.target.value)}
                  style={{ flex: 1, padding: '10px', borderRadius: '8px', border: '1px solid #dfe6e9' }}
                />
                <button type="submit" style={{ padding: '10px 20px', backgroundColor: '#00b894', color: 'white', border: 'none', borderRadius: '8px', fontWeight: '600' }}>Add</button>
              </form>

              <h4 style={{ marginBottom: '10px' }}>Who's coming:</h4>
              <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', marginBottom: '25px' }}>
                {expandedEvent.attendees?.map(person => (
                  <span key={person._id} style={{ background: '#e1f5fe', color: '#0288d1', padding: '4px 12px', borderRadius: '15px', fontSize: '12px', fontWeight: '600' }}>
                    {person.name}
                  </span>
                ))}
              </div>

              <button onClick={() => setExpandedEvent(null)} style={{ width: '100%', background: '#f0f2f5', border: 'none', padding: '12px', borderRadius: '10px', cursor: 'pointer', fontWeight: '600' }}>Close</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
